        }),
      getForegroundWindow: () =>
        load({
          library: user32,
          funcName: "GetForegroundWindow",
          retType: DataType.BigInt,
          paramsType: [],
          paramsValue: [],
        }) as bigint,
      getWindowClassName: (windowHandle) => {
        const buffer = Buffer.alloc(512);
        const length = load({
          library: user32,
          funcName: "GetClassNameW",
