      Action: {
        ScreenshotWindow: {
          id: window.id,
          write_to_disk: true,
          show_pointer: false,
          path: imagePath,
        },
      },
    });
    await captured;
    const png = await readPortalPng(NodeURL.pathToFileURL(imagePath).href);
    const after = decodeWindows(await request(path, "Windows")).Windows.find(
      (item) => item.id === window.id,
    );
