const OrchestrationV2InternalCommand = Schema.Union([
  // Guest share commands the server issues after checking T3 Connect and the guest token.
  Schema.Struct({
    type: Schema.Literal("thread.guest-share.open"),
    commandId: CommandId,
    threadId: ThreadId,
