      registry.readMachineKey(subkey).pipe(
        Effect.mapError(
          (cause) =>
            new ManagedPolicyFileError({
              path,
              reason:
                cause.code === undefined
                  ? "this Blackcrab install cannot load its registry reader; reinstall Blackcrab"
                  : `the registry cannot be read (${cause.message})`,
              cause,
            }),
        ),
      );
