      disabled,
      warnings,
      resourceAttributes: resource.value,
      traces: signals?.traces.signal ?? OtelSignal.Unset(),
      metrics: signals?.metrics.signal ?? OtelSignal.Unset(),
      logs: signals?.logs.signal ?? OtelSignal.Unset(),
