      variable: `T3CODE_OTLP_${signal.toUpperCase()}_URL`,
    };
  }
  return OtelSignal.$match(otel[signal], {
    Export: ({ url, variable, protocol, headers }): SignalEndpoint => ({
      url,
      export: { protocol, headers, exportIntervalMs: t3.export.exportIntervalMs },
      source: "environment",
      variable,
