    const workArea = { x: 0, y: 0, width: 1920, height: 1080 };
    assert.deepEqual(
      DesktopWindow.cascadeWindowBounds({ x: 100, y: 80, width: 1200, height: 800 }, workArea),
      { x: 132, y: 112, width: 1200, height: 800 },
