      "javascript:alert(1)",
      "about:blank",
      "blob:t3code://app/0b5e2c4a",
    ]) {
      assert.isFalse(
        DesktopWindow.isSameOriginRendererNavigation({
          applicationUrl: "t3code://app/",
          navigationUrl,
        }),
        navigationUrl,
      );
    }
    assert.isFalse(
      DesktopWindow.isSameOriginRendererNavigation({
