      const harness = yield* makeHarness({
        beforeBootstrap: Ref.getAndUpdate(relayBlips, (count) => count - 1).pipe(
          Effect.flatMap((count) =>
            count > 0
              ? Effect.fail(
                  new ManagedRelay.ManagedRelayRequestTimeoutError({
                    activity: "Relay environment connection",
