      toolSurface: "computer",
      toolSource: { key: "computer-use", name: "Computer Use", kind: "computer" },
    });
    expect(
      extractToolActivityPresentation({
        ...item,
        input: { code: "await fetch('http://127.0.0.1/json/list');" },
      }),
