  if (triageEnvironmentId !== null && canTriage) {
    actionItems.push({
      kind: "action",
      value: "action:triage",
      searchTerms: ["triage", "bug", "issue", "report", "broken", "debug", "help", "support"],
      title: "Triage an issue",
